// Payment Reminder Bot: core logic (ported from main.py)
const STAGES = [
 {
  "name": "due soon",
  "min_days": -3,
  "max_days": 0,
  "template": "Hi {client}, a quick heads-up that invoice {invoice} for NGN {amount} is due on {due}. Thank you!"
 },
 {
  "name": "friendly",
  "min_days": 1,
  "max_days": 7,
  "template": "Hi {client}, just a reminder that invoice {invoice} (NGN {amount}) was due on {due}. If it's already sent, please ignore this. Thanks!"
 },
 {
  "name": "firm",
  "min_days": 8,
  "max_days": 21,
  "template": "Dear {client}, invoice {invoice} for NGN {amount} is now {days} days overdue. Please arrange payment this week or let us know when to expect it."
 },
 {
  "name": "final",
  "min_days": 22,
  "max_days": 45,
  "template": "Dear {client}, this is a final reminder: invoice {invoice} (NGN {amount}) is {days} days overdue. Please settle within 5 working days to avoid service suspension.",
  "escalate": true
 },
 {
  "name": "escalate",
  "min_days": 46,
  "max_days": 9999,
  "template": "Dear {client}, invoice {invoice} (NGN {amount}) is {days} days overdue and has been passed to our accounts manager, who will contact you.",
  "escalate": true
 }
];
// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

const today = new Date(); today.setHours(0, 0, 0, 0);
const out = [];
for (const inv of input) {
  if (['paid', 'disputed'].includes(inv.status)) continue;
  const days = Math.round((today - new Date(inv.due_date + 'T00:00:00')) / 864e5);
  const st = STAGES.find(s => days >= s.min_days && days <= s.max_days);
  if (!st) continue;
  const message = st.template.replace('{client}', inv.client).replace('{invoice}', inv.invoice)
    .replace('{amount}', Number(inv.amount).toLocaleString()).replace('{due}', inv.due_date).replace('{days}', Math.abs(days));
  out.push({ route: inv.channel, to: inv.contact, invoice: inv.invoice, client: inv.client, stage: st.name, days_overdue: days,
             escalate: !!st.escalate, message });
}
return out.map(json => ({ json }));
